/**
 * Zod schemas for the PLP REST API.
 *
 * Backend reference: backend/backend/docs/PLP_FRONTEND_IMPLEMENTATION.md §4.
 * Endpoints:
 *   GET /api/v1/plp/{website_code}/{category_id}                              → PLPResponseSchema
 *   GET /api/v1/plp/{website_code}/{category_id}/facets/{facet_key}/values    → FacetsValuesResponseSchema
 *
 * Shape-first per Non-Negotiable #2 ("Trust Nothing"). Loose inner types
 * with `.passthrough()` so backend-side additions don't break parsing.
 * Arrays default to `[]`. Most scalar fields are `.optional()` since the
 * payload mixes required and optional shape across product variants.
 */

import { z } from 'zod';

// ── Primitives ──────────────────────────────────────────────────

const NumOrString = z.union([z.number(), z.string()]);

// Money fields can arrive as number, string, null, or absent — backend
// normalization is loose enough that we accept all four.
const PriceLike = NumOrString.nullable().optional();

// ── Variant images on a product ─────────────────────────────────

// Backend returns `null` for variant_image string fields routinely
// (alt_text is the most common — empty strings on a BC variant come
// through as null). Accepting null on every string keeps the response
// parseable instead of failing the whole page over a missing alt.
export const PLPVariantImageSchema = z.object({
  variant_id: NumOrString.nullish(),
  sku: z.string().nullish(),
  url: z.string().nullish(),
  alt_text: z.string().nullish(),
  variant_display_name: z.string().nullish(),
}).passthrough();

// ── Flag badge on a product ─────────────────────────────────────

export const PLPFlagSchema = z.object({
  key: z.string().optional(),
  label: z.string().optional(),
  icon_url: z.string().nullable().optional(),
  color: z.string().nullable().optional(),
}).passthrough();

// ── Read-only star rating (per-product) ────────────────────────
//
// The renderer-facing shape: 5 stars + optional review count. Half-stars
// supported (anything ≥ x.25 and < x.75 renders as a half star).
//
// The live backend does not send this shape — it sends `reviews` (below).
// `rating` stays on the schema because fixtures and non-PLP producers use
// it, and because it is the shape every renderer reads. Consumers should
// go through `resolveProductRating()` rather than reading either field
// directly, so both producers land on the same stars.
export const PLPRatingSchema = z.object({
  value: z.number().min(0).max(5),
  count: z.number().int().nonnegative().optional(),
}).passthrough();

// ── Review aggregate as the backend actually sends it ──────────
//
// `app/api/plp.py` serializes reviews as `{average_rating, review_count,
// summary}` and omits the block entirely for products with neither a
// rating nor a summary. `average_rating` is null when a product has a
// review summary but no numeric rating, so it is nullable independently
// of the block.
//
// This block CANNOT fail a parse, by construction. It rides on every reviewed
// product in a live response, so any assertion here — range or type — is not a
// validation, it is a blast radius: one bad field fails the product, fails the
// products array, fails the whole `PLPResponseSchema`, and `fetchPLP` throws
// where the grid used to render. A cosmetic data problem must not empty the
// page.
//
// So: numbers ride `NumOrString` (the same reason `PriceLike` exists above —
// a Decimal serialized by the backend arrives as a JSON string), and every
// field carries `.catch()` so even a shape nobody predicted degrades to null
// instead of throwing. `resolveProductRating` is the layer that coerces and
// clamps whatever survives into the 0-5 the renderer can draw.
export const PLPReviewsSchema = z.object({
  average_rating: NumOrString.nullable().optional().catch(null),
  review_count: NumOrString.nullable().optional().catch(null),
  summary: z.string().nullable().optional().catch(null),
}).passthrough();

// ── Bulk-pricing tier ──────────────────────────────────────────

export const PLPBulkPricingTierSchema = z.object({
  min_qty: z.number().optional(),
  max_qty: z.number().nullable().optional(),
  price: PriceLike,
  type: z.string().optional(),
}).passthrough();

// ── Single product ─────────────────────────────────────────────

export const PLPProductSchema = z.object({
  id: NumOrString,
  sku: z.string().nullable().optional(),
  name: z.string().nullable().optional(),
  // Display-only brand / product-line label (e.g. "TRACT OPTICS"). Optional —
  // mirrors the carousel product schema; rendered above the name when present.
  brand: z.string().nullable().optional(),
  url: z.string().nullable().optional(),
  price: PriceLike,
  retail_price: PriceLike,
  sale_price: PriceLike,
  image_url: z.string().nullable().optional(),
  alternate_image_url: z.string().nullable().optional(),
  variant_images: z.array(PLPVariantImageSchema).default([]),
  flags: z.array(PLPFlagSchema).default([]),
  bulk_pricing: z.array(PLPBulkPricingTierSchema).default([]),
  pinned_position: z.number().nullable().optional(),
  use_case_ids: z.array(z.number()).default([]),
  rating: PLPRatingSchema.nullable().optional(),
  reviews: PLPReviewsSchema.nullable().optional(),
}).passthrough();

// ── Category metadata ──────────────────────────────────────────

export const PLPCategoryChildSchema = z.object({
  id: NumOrString,
  name: z.string().optional(),
  url: z.string().optional(),
  product_count: z.number().optional(),
}).passthrough();

export const PLPCategoryRedirectSchema = z.object({
  id: NumOrString,
  name: z.string().optional(),
  url: z.string().optional(),
}).passthrough();

export const PLPCategorySchema = z.object({
  id: NumOrString,
  name: z.string().optional(),
  description: z.string().nullable().optional(),
  children: z.array(PLPCategoryChildSchema).default([]),
  redirect_to: PLPCategoryRedirectSchema.nullable().optional(),
}).passthrough();

// ── Facets ─────────────────────────────────────────────────────

// Deferred-typing contract for `value`:
// `value` is `unknown` because the runtime type depends on the parent facet's
// `type` (string for attributes, number-id for use_case, string flag-key,
// number bucket bound for price_range, etc.) and we'd rather not commit to a
// discriminated union ahead of the backend stabilizing the surface. Any
// renderer reading `value` MUST narrow before stringification — call
// `narrowFacetValue(raw)` below or do a `typeof` guard inline. Forgetting the
// narrow ships `[object Object]` into a tile.
export const PLPFacetValueSchema = z.object({
  value: z.unknown().optional(),
  label: z.string().nullable().optional(),
  count: z.number().optional(),
  value_id: z.union([z.string(), z.number()]).nullable().optional(),
  selected: z.boolean().optional(),
  // price-range buckets
  min: z.number().nullable().optional(),
  max: z.number().nullable().optional(),
  currency_code: z.string().nullable().optional(),
}).passthrough();

export const PLPFacetSchema = z.object({
  key: z.string(),
  label: z.string().nullable().optional(),
  // type ∈ attribute | use_case | flag | price_range | rating | in_stock — kept loose
  type: z.string(),
  values: z.array(PLPFacetValueSchema).default([]),
}).passthrough();

// ── Pagination ─────────────────────────────────────────────────

export const PLPPaginationSchema = z.object({
  next_cursor: z.string().nullable().optional(),
  prev_cursor: z.string().nullable().optional(),
  total_estimate: z.number().optional(),
  page_size: z.number().optional(),
}).passthrough();

// ── Top-level response ─────────────────────────────────────────

export const PLPResponseSchema = z.object({
  category: PLPCategorySchema,
  products: z.array(PLPProductSchema).default([]),
  facets: z.array(PLPFacetSchema).default([]),
  pagination: PLPPaginationSchema.optional(),
  sort: z.string().nullable().optional(),
  applied_rule_ids: z.array(z.number()).default([]),
}).passthrough();

// ── Show-more facet-values endpoint ────────────────────────────

export const FacetsValuesResponseSchema = z.object({
  facet_key: z.string().optional(),
  values: z.array(PLPFacetValueSchema).default([]),
  total_estimate: z.number().optional(),
  has_more: z.boolean().optional(),
}).passthrough();

// ── Inferred types ─────────────────────────────────────────────

export type PLPResponse = z.infer<typeof PLPResponseSchema>;
export type PLPProduct = z.infer<typeof PLPProductSchema>;
export type PLPCategory = z.infer<typeof PLPCategorySchema>;
export type PLPFacet = z.infer<typeof PLPFacetSchema>;
export type PLPFacetValue = z.infer<typeof PLPFacetValueSchema>;
export type PLPVariantImage = z.infer<typeof PLPVariantImageSchema>;
export type PLPFlag = z.infer<typeof PLPFlagSchema>;
export type PLPBulkPricingTier = z.infer<typeof PLPBulkPricingTierSchema>;
export type PLPRating = z.infer<typeof PLPRatingSchema>;
export type PLPReviews = z.infer<typeof PLPReviewsSchema>;
export type PLPPagination = z.infer<typeof PLPPaginationSchema>;
export type FacetsValuesResponse = z.infer<typeof FacetsValuesResponseSchema>;

// ── Helpers ────────────────────────────────────────────────────

/**
 * Narrow a `PLPFacetValue.value` (typed `unknown`) into something safe to
 * render. Returns the input as `string | number | boolean | null` if it's
 * a primitive; returns `null` for anything else (objects, arrays, undefined)
 * so the renderer can fall back to a label or hide the chip.
 *
 * Usage:
 *   const narrowed = narrowFacetValue(facetValue.value);
 *   if (narrowed === null) return facetValue.label ?? '';
 *   return String(narrowed);
 *
 * Centralizes the `[object Object]` defense so renderers don't reinvent it.
 */
export function narrowFacetValue(
  raw: unknown,
): string | number | boolean | null {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'string' || typeof raw === 'number' || typeof raw === 'boolean') {
    return raw;
  }
  return null;
}

/**
 * Resolve the star rating to render for a product, from whichever of the
 * two producer shapes is present.
 *
 * The backend sends `reviews: {average_rating, review_count}`; fixtures and
 * older producers send `rating: {value, count}`. Renderers read one shape,
 * so the projection happens here rather than in each tile.
 *
 * Precedence: an explicit `rating` decides outright — if it is present, the
 * `reviews` block is not consulted at all, including when the explicit value
 * is 0. Returns null when there is nothing to draw: no block at all, a review
 * block carrying only a summary (`average_rating: null`), or a non-positive
 * rating from either source. A zero-star row is noise on a tile, so it renders
 * as no rating rather than five empties.
 */
export function resolveProductRating(
  product: Pick<Partial<PLPProduct>, 'rating' | 'reviews'> | null | undefined,
): PLPRating | null {
  // PRESENCE of `rating` decides, not its value: a producer that sends the
  // field has already decided what to display, and deciding on "no stars"
  // (value 0 — moderated or withdrawn reviews) is one of the things it can
  // decide. Falling through to `reviews` here would redraw stars that
  // producer deliberately suppressed.
  const explicit = product?.rating;
  if (explicit) return explicit.value > 0 ? explicit : null;

  const average = toFiniteNumber(product?.reviews?.average_rating);
  if (average === null || average <= 0) return null;
  // Clamp rather than trust: the schema above accepts whatever arrives so one
  // odd row can't fail the page, which makes this the place that keeps a 7.4
  // from drawing seven stars.
  const value = Math.min(average, 5);

  // Floor BEFORE the test, so a fractional 0.5 resolves to "no count" rather
  // than to a `count: 0` that claims zero reviews — the no-count path has to
  // return one shape, not two.
  const count = toFiniteNumber(product?.reviews?.review_count);
  const whole = count === null ? 0 : Math.floor(count);
  return whole > 0 ? { value, count: whole } : { value };
}

/** Number, numeric string, or null — mirrors what `NumOrString` lets through. */
function toFiniteNumber(value: unknown): number | null {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'string' && value.trim()) {
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}
